UPDATE ${tableName}
SET ai_judge_status = #{toStatus},
    modifier_date = NOW()
WHERE warning_order_id = #{warningOrderId}
  AND ai_judge_status = #{fromStatus}

UPDATE ${tableName}
SET ai_judge_status = #{aiJudgeStatus},
    modifier_date = NOW()
WHERE warning_order_id = #{warningOrderId}

UPDATE ${tableName}
SET ai_judge_status = #{pendingStatus},
    modifier_date = NOW()
WHERE delete_flag = '0'
  AND ai_judge_status = #{processingStatus}
  AND modifier_date < DATE_SUB(NOW(), INTERVAL #{timeoutMinutes} MINUTE)

UPDATE ${tableName}
SET agent_extend_field = #{agentExtendField},
    modifier_date = NOW()
WHERE warning_order_id = #{warningOrderId}
